param([string]$Repo='E:\3dconformergenerationcode\4dadapter-lsgoba-musigma-reliability-factorial',[string]$Python='E:\miniconda\envs\etflow-5080-v2\python.exe',[int]$HeadSupervisorPid=42564,[string]$ReadyEventName='')
$ErrorActionPreference='Stop';$runtime=Join-Path $Repo 'reports\ecir_mvr\sixs_deltaq_single_seed_pilot\runtime';New-Item -ItemType Directory -Path $runtime -Force|Out-Null;$status=Join-Path $runtime 'PIPELINE_STATUS.json';$headStatus=Join-Path $Repo 'reports\ecir_mvr\sixs_deltaq_learnability_audit\runtime\AUDIT_STATUS.json';$guard=Join-Path $Repo 'scripts\run_sixs_deltaq_overfit_native_guard.py';$train=Join-Path $Repo 'scripts\run_sixs_deltaq_exploratory_full_train.py';$stage=Join-Path $Repo 'scripts\run_sixs_deltaq_single_seed_stage.py';$cfg=Join-Path $Repo 'configs\sixs_deltaq_single_seed_pilot.json';$cfgSha=(Get-FileHash $cfg -Algorithm SHA256).Hash.ToLowerInvariant();$commit=(&git -C $Repo rev-parse HEAD).Trim()
function W([hashtable]$x){$t="$status.tmp.$PID";[IO.File]::WriteAllText($t,($x|ConvertTo-Json -Depth 10)+[Environment]::NewLine);Move-Item $t $status -Force}
$s=@{schema_version='sixs-v2-deltaq-exploratory-pipeline-v1';pipeline_status='WAITING_FOR_HEAD_ONLY';current_stage='WAITING_FOR_HEAD_ONLY_DIAGNOSTIC';worker_pid=$null;supervisor_pid=[int]$PID;head_supervisor_pid=$HeadSupervisorPid;stage_start_time=[DateTimeOffset]::Now.ToString('o');stage_end_time=$null;stage_exit_code=$null;git_commit=$commit;config_sha256=$cfgSha;seed=307;checkpoint_path=(Join-Path $Repo 'artifacts\ecir_mvr\sixs_deltaq_single_seed_pilot\DELTAQ_SEED307_FULL.pt');stdout_path=$null;stderr_path=$null;failure_reason=$null;original_strict_sanity_gate='FAIL_BY_PREDECLARED_50_PERCENT_GATE';deltaq_learning_signal='POSITIVE';bond_mae_reduction_percent=44.3;angle_mae_reduction_percent=38.9;exploratory_full_train_allowed='YES';exploratory_development_only='YES';formal_confirmatory_result='NO';formal_test_read='NO';avg_old_final_used_for_tuning='NO'};W $s
if($ReadyEventName){$e=[Threading.EventWaitHandle]::OpenExisting($ReadyEventName);[void]$e.Set();$e.Dispose()}
function Reusable([string]$name){$p=Join-Path $runtime "${name}_COMPLETED.json";if(-not(Test-Path $p)){return $false};try{$m=Get-Content $p -Raw|ConvertFrom-Json;return $m.status-eq'COMPLETED'-and$m.pipeline_identity_sha256-eq$cfgSha}catch{return $false}}
function Run([string]$name,[string[]]$a,[bool]$needMarker=$true){
 if($needMarker-and(Reusable $name)){return};$o=Join-Path $runtime "${name}_STDOUT.log";$er=Join-Path $runtime "${name}_STDERR.log";[IO.File]::WriteAllText($o,'');[IO.File]::WriteAllText($er,'');$s.pipeline_status='RUNNING';$s.current_stage=$name;$s.stdout_path=$o;$s.stderr_path=$er;$s.stage_start_time=[DateTimeOffset]::Now.ToString('o');$s.failure_reason=$null
 $root=Split-Path -Parent $Python;$win=[Environment]::GetFolderPath('Windows');$git=Split-Path -Parent (Get-Command git.exe).Source;$path=@($root,(Join-Path $root 'Library\mingw-w64\bin'),(Join-Path $root 'Library\usr\bin'),(Join-Path $root 'Library\bin'),(Join-Path $root 'Scripts'),$git,(Join-Path $win 'System32'),$win)-join';';$si=New-Object Diagnostics.ProcessStartInfo;$si.FileName=$Python;$si.Arguments=($a|ForEach-Object{'"'+$_+'"'})-join' ';$si.WorkingDirectory=$Repo;$si.UseShellExecute=$false;$si.CreateNoWindow=$true;$si.RedirectStandardOutput=$true;$si.RedirectStandardError=$true;$si.EnvironmentVariables['PATH']=$path;$si.EnvironmentVariables['CONDA_PREFIX']=$root;$si.EnvironmentVariables['PYTHONNOUSERSITE']='1';$p=New-Object Diagnostics.Process;$p.StartInfo=$si;if(-not$p.Start()){throw "cannot start $name"};$s.worker_pid=[int]$p.Id;W $s;$ot=$p.StandardOutput.ReadToEndAsync();$et=$p.StandardError.ReadToEndAsync();$p.WaitForExit();$ot.Wait();$et.Wait();$p.Refresh();[IO.File]::WriteAllText($o,$ot.Result);[IO.File]::WriteAllText($er,$et.Result);$s.stage_exit_code=[int]$p.ExitCode;$s.stage_end_time=[DateTimeOffset]::Now.ToString('o');W $s;if($p.ExitCode-ne0){throw "$name exited $($p.ExitCode)"};if($needMarker-and-not(Reusable $name)){throw "$name completion marker missing"}
}
try{
 $hp=Get-Process -Id $HeadSupervisorPid -ErrorAction SilentlyContinue;if($null-ne$hp){$hp.WaitForExit()};$hs=Get-Content $headStatus -Raw|ConvertFrom-Json;if($hs.status-ne'COMPLETED'){throw "HEAD_ONLY_AUDIT_ENGINEERING_STATUS_$($hs.status)"}
 Run '01_FULL_TRAIN_WORKER' @($guard,$train) $false;Run '01_FULL_TRAIN' @($stage,'finalize-train') $true;Run '02_ETFLOW_EVAL' @($stage,'etflow') $true;Run '03_AVGFLOW_EVAL' @($stage,'avgflow') $true;Run '04_DITMC_EVAL' @($stage,'ditmc') $true;Run '05_XTB_EVAL' @($stage,'xtb') $true;Run '06_AGGREGATION' @($stage,'aggregate') $true;$s.pipeline_status='COMPLETED';$s.current_stage='COMPLETED';$s.worker_pid=$null;$s.stage_exit_code=0;$s.stage_end_time=[DateTimeOffset]::Now.ToString('o');W $s
}catch{$s.pipeline_status='FAILED';$s.stage_end_time=[DateTimeOffset]::Now.ToString('o');$s.failure_reason=$_.Exception.Message;W $s;exit 1}
